int insideCount = 0;
std::random_device rd;
std::mt19937 gen(rd());
std::uniform_real_distribution<double> dist(-1.0, 1.0);
for (int i = 0; i < numberOfChecks; ++i) {
    double x, y, z, len;
    do {
        x = dist(gen);
        y = dist(gen);
        z = dist(gen);
        len = std::sqrt(x * x + y * y + z * z);
    } while (len < 1e-12);
    x /= len; y /= len; z /= len;
    auto ray = CGAL::Ray_3<decltype(p)>(p, p + CGAL::Vector_3<decltype(p)>(x, y, z));
    std::size_t intersections = tree.number_of_intersections(ray);
    if (intersections % 2 == 1) {
        ++insideCount;
    }
}
return insideCount > numberOfChecks / 2;

